// closerAssertStatsZeroOnError asserts Stats returns zero alongside any error.
func closerAssertStatsZeroOnError(
	tb testing.TB,
	c Closer,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := c.Stats(ctx)
	if err == nil {
		tb.Skip("Stats answered for a cancelled context, so this check has no error to inspect")
	}

	var zero int
	if got != zero {
		tb.Errorf("Stats must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

// closerAssertCloseIdempotent asserts a second Close after a clean one is accepted.
func closerAssertCloseIdempotent(
	tb testing.TB,
	c Closer,
) {
	tb.Helper()
	ctx := tb.Context()

	if err := c.Close(ctx); err != nil {
		tb.Fatalf("Close must succeed before its repeat can be judged: got %v", err)
	}
	if err := c.Close(ctx); err != nil {
		tb.Errorf("a second Close after a clean one must change nothing: got %v", err)
	}
}

